package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.JavaType;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.*;
import com.fasterxml.jackson.databind.deser.KeyDeserializer;
import com.fasterxml.jackson.databind.deser.impl.PropertyBasedCreator;
import com.fasterxml.jackson.databind.deser.impl.PropertyValueBuffer;
import com.fasterxml.jackson.databind.deser.impl.ReadableObjectId.Referring;
import com.fasterxml.jackson.databind.deser.std.StdDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ArrayBuilders;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.HashSet;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.mock;

public class MapDeserializer_isCachable_TriageGen2Test {

    @Test
    public void testIsCachable_AllNull_ReturnsTrue() {
        // Arrange
        JavaType mapType = mock(JavaType.class);
        // Constructor: (JavaType mapType, ValueInstantiator valueInstantiator, KeyDeserializer keyDeser, JsonDeserializer<Object> valueDeser, TypeDeserializer valueTypeDeser)
        // To make isCachable return true, _valueTypeDeserializer must be null and _ignorableProperties must be null
        MapDeserializer deserializer = new MapDeserializer(
                mapType,
                null,
                null,
                null,
                null
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        Assert.assertTrue("Should be cachable when both deserializer and ignorable properties are null", result);
    }

    @Test
    public void testIsCachable_ValueTypeDeserializerNotNull_ReturnsFalse() {
        // Arrange
        JavaType mapType = mock(JavaType.class);
        TypeDeserializer valueTypeDeserializer = mock(TypeDeserializer.class);

        MapDeserializer deserializer = new MapDeserializer(
                mapType,
                null,
                null,
                null,
                valueTypeDeserializer
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        Assert.assertFalse("Should not be cachable when _valueTypeDeserializer is not null", result);
    }

    @Test
    public void testIsCachable_IgnorablePropertiesNotNull_ReturnsFalse() {
        // Arrange
        JavaType mapType = mock(JavaType.class);

        // Using the protected constructor to inject ignorable properties
        // MapDeserializer(MapDeserializer src, KeyDeserializer keyDeser, JsonDeserializer<Object> valueDeser, TypeDeserializer valueTypeDeser, HashSet<String> ignorable)

        // First create a base instance
        MapDeserializer src = new MapDeserializer(mapType, null, null, null, null);

        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("someProperty");

        // We need to access the protected constructor. 
        // Since the test is in the same package (com.fasterxml.jackson.databind.deser.std), we can access it.
        MapDeserializer deserializer = new MapDeserializer(
                src,
                null,
                null,
                null,
                ignorable
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        Assert.assertFalse("Should not be cachable when _ignorableProperties is not null", result);
    }

    @Test
    public void testIsCachable_BothNotNull_ReturnsFalse() {
        // Arrange
        JavaType mapType = mock(JavaType.class);
        TypeDeserializer valueTypeDeserializer = mock(TypeDeserializer.class);
        HashSet<String> ignorable = new HashSet<>();
        ignorable.add("prop");

        MapDeserializer src = new MapDeserializer(mapType, null, null, null, null);

        MapDeserializer deserializer = new MapDeserializer(
                src,
                null,
                null,
                valueTypeDeserializer,
                ignorable
        );

        // Act
        boolean result = deserializer.isCachable();

        // Assert
        Assert.assertFalse("Should not be cachable when both are not null", result);
    }
}
